import{_ as d,C as e,o,c as r,j as i,E as n,a as s,a2 as t}from"./chunks/framework.C21TwvGF.js";const k=JSON.parse(`{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (Android)","link":"/10-sinf-android/"},"n":2,"bob":"I-bob · Android loyihalarini boshqarish va versiya nazorati tizimlari","lessons":[{"g":4,"title":"4-dars: Dependency management va ziddiyatlarni hal qilish","lead":"Dependency management va ziddiyatlarni hal qilish: tranzitiv bog'liqliklar, exclude, resolutionStrategy","link":"/10-sinf-android/hafta-02/dars-1","slide":"/slaydlar/10-sinf-android/hafta-02/dars-1.html","test":"/slaydlar/10-sinf-android/hafta-02/dars-1-test.html"},{"g":5,"title":"5-dars: ProGuard va R8 yordamida kodni optimallashtirish (1-qism)","lead":"ProGuard va R8 yordamida kodni optimallashtirish (1-qism): Shrinking, Obfuscation, Optimization","link":"/10-sinf-android/hafta-02/dars-2","slide":"/slaydlar/10-sinf-android/hafta-02/dars-2.html","test":"/slaydlar/10-sinf-android/hafta-02/dars-2-test.html"},{"g":6,"title":"6-dars: ProGuard va R8 qoidalari bilan ishlash (2-qism: Amaliyot)","lead":"ProGuard va R8 qoidalari bilan ishlash (2-qism): -keep qoidalari, Reflection, mapping.txt","link":"/10-sinf-android/hafta-02/dars-3","slide":"/slaydlar/10-sinf-android/hafta-02/dars-3.html","test":"/slaydlar/10-sinf-android/hafta-02/dars-3-test.html"}],"test":"/slaydlar/10-sinf-android/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-android/hafta-02/index.md","filePath":"10-sinf-android/hafta-02/index.md"}`),h={name:"10-sinf-android/hafta-02/index.md"},c={class:"blk"},m={id:"uyga-vazifa",tabindex:"-1"};function u(g,a,y,f,q,p){const l=e("Icon");return o(),r("div",null,[i("div",c,[i("h2",m,[n(l,{name:"house"}),a[0]||(a[0]=s(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=t('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar to&#39;plami. Har bir vazifa 25–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_4-dars-dependency-management-va-ziddiyatlarni-hal-qilish-tranzitiv-bog-liqliklar" tabindex="-1">4-dars: Dependency management va ziddiyatlarni hal qilish (Tranzitiv bog&#39;liqliklar) <a class="header-anchor" href="#_4-dars-dependency-management-va-ziddiyatlarni-hal-qilish-tranzitiv-bog-liqliklar" aria-label="Permalink to &quot;4-dars: Dependency management va ziddiyatlarni hal qilish (Tranzitiv bog&#39;liqliklar)&quot;">​</a></h3><ol><li>Android Studio loyihangiz terminalida <code>./gradlew app:dependencies --configuration releaseRuntimeClasspath</code> buyrug&#39;ini ishga tushiring.</li><li>Natijada chiqqan bog&#39;liqliklar daraxtidan bitta tranzitiv bog&#39;liqlikni (masalan, <code>androidx.core:core</code> yoki <code>kotlinx-coroutines</code>) aniqlang va u qaysi asosiy kutubxona orqali loyihaga kirib kelganini daftaringizga yozing.</li><li>Loyihada sun&#39;iy ravishda versiya ziddiyati hosil qiling va <code>app/build.gradle</code> faylida <code>exclude group:</code> yoki <code>resolutionStrategy.force</code> yordamida uni yagona barqaror versiyaga moslashtiring.</li></ol><hr><h3 id="_5-dars-proguard-va-r8-yordamida-kodni-optimallashtirish-1-qism" tabindex="-1">5-dars: ProGuard va R8 yordamida kodni optimallashtirish (1-qism) <a class="header-anchor" href="#_5-dars-proguard-va-r8-yordamida-kodni-optimallashtirish-1-qism" aria-label="Permalink to &quot;5-dars: ProGuard va R8 yordamida kodni optimallashtirish (1-qism)&quot;">​</a></h3><ol><li>Android Studio&#39;da <code>app/build.gradle</code> (yoki <code>.kts</code>) faylini oching va <code>buildTypes.release</code> blokiga quyidagi sozlamalarni kiriting: <ul><li><code>isMinifyEnabled = true</code> (yoki Groovy&#39;da <code>minifyEnabled true</code>)</li><li><code>isShrinkResources = true</code> (yoki Groovy&#39;da <code>shrinkResources true</code>)</li></ul></li><li>Terminalda <code>./gradlew assembleRelease</code> buyrug&#39;i orqali Release APK hosil qiling.</li><li>Android Studio menyusidan <strong>Build &gt; Analyze APK...</strong> bo&#39;limini oching va yaratilgan Release APK&#39;ni kiring: <ul><li>Debug va Release APK hajmini solishtiring;</li><li><code>classes.dex</code> ichidagi klass nomlari qanday qisqarganini (masalan, <code>a.b.c</code>) ko&#39;zdan kechiring.</li></ul></li></ol><hr><h3 id="_6-dars-proguard-va-r8-qoidalari-bilan-ishlash-2-qism-amaliyot" tabindex="-1">6-dars: ProGuard va R8 qoidalari bilan ishlash (2-qism: Amaliyot) <a class="header-anchor" href="#_6-dars-proguard-va-r8-qoidalari-bilan-ishlash-2-qism-amaliyot" aria-label="Permalink to &quot;6-dars: ProGuard va R8 qoidalari bilan ishlash (2-qism: Amaliyot)&quot;">​</a></h3><ol><li>Loyihangizda serverdan keladigan ma&#39;lumotlar uchun kamida 2 ta data class yarating: <ul><li><code>UserProfile(val id: Long, val name: String, val role: String)</code></li><li><code>OrderDetails(val orderId: String, val totalSum: Double)</code></li></ul></li><li><code>UserProfile</code> klassini <code>app/proguard-rules.pro</code> faylida <code>-keep class ... { *; }</code> qoidasi orqali himoyalang.</li><li><code>OrderDetails</code> klassiga esa <code>androidx.annotation.Keep</code> kutubxonasidagi <code>@Keep</code> annotatsiyasini qo&#39;llang.</li><li>Loyihani qayta Release build qiling va <code>app/build/outputs/mapping/release/mapping.txt</code> faylini ochib, ushbu klasslar qanday saqlanganini tekshiring.</li></ol><hr>',11))])])}const v=d(h,[["render",u]]);export{k as __pageData,v as default};
